  {{ds:component/card|href={{cms:item/12565c25-b278-43dc-aba1-31def311efa4}}|tag=Endpoint · Stable|title=Connectors|description=Create, list, and rotate credentials for connectors.}}
  {{ds:component/card|href={{cms:item/cc2e9b39-d44c-42c9-ad82-8ed72200e699}}|tag=Endpoint · Stable|title=Transforms|description=Create and list transform steps for a pipeline.}}
  {{ds:component/card|href={{cms:item/84099cd7-f352-4887-85a1-2bfdc6e700f0}}|tag=Endpoint (v3) · Stable|title=Events|description=Query and replay events that have flowed through a pipeline via the v3 API.}}
  {{ds:component/card|href={{cms:item/6e2fe20d-5b70-4f5b-9216-71f1d0b736b1}}|tag=Endpoint · Stable|title=Webhooks|description=Subscribe to platform lifecycle events over outbound HTTP.}}
  {{ds:component/card|href={{cms:item/6ff7090a-d1a9-4f90-91ae-6c8e3bd5942f}}|tag=Reference · Stable|title=Rate limits|description=Standard-tier limits, rate limit headers, and cursor pagination envelope.}}
  {{ds:component/card|href={{cms:item/4fcc4b70-40ef-4a45-8644-81369d60758e}}|tag=Reference · Stable|title=Error reference|description=The v2 API's error response shape and error handling.}}
